import numpy as np
y=dP_dt
def run(k,pows,tb):
    e=np.exp(-k*t)
    T={'1':np.ones_like(t),'t':t,'t2':t**2,'e':e,'te':t*e}
    cols=[];names=[]
    for pw in pows:
        for tn in tb:
            cols.append(T[tn]*P**pw);names.append(f'{tn}*P^{pw}')
    A=np.column_stack(cols)
    c=np.linalg.lstsq(A,y,rcond=None)[0]
    r=y-A@c
    return np.mean(r**2)/np.var(y),names,c
